CREATE TABLE "AiGovernanceEscalation" ("id" TEXT NOT NULL,"agencyId" TEXT NOT NULL,"sourceType" TEXT NOT NULL,"sourceId" TEXT NOT NULL,"severity" TEXT NOT NULL,"title" TEXT NOT NULL,"reason" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"level" INTEGER NOT NULL DEFAULT 1,"ownerId" TEXT,"acknowledgedAt" TIMESTAMP(3),"resolvedAt" TIMESTAMP(3),"dueAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AiGovernanceEscalation_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "AiGovernanceEscalation_agencyId_sourceType_sourceId_key" ON "AiGovernanceEscalation"("agencyId","sourceType","sourceId");CREATE INDEX "AiGovernanceEscalation_agencyId_status_dueAt_idx" ON "AiGovernanceEscalation"("agencyId","status","dueAt");